CREATE TABLE IF NOT EXISTS "trusted_fingerprints" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "fingerprint" TEXT NOT NULL, "label" TEXT, "note" TEXT, "last_ip" TEXT, "last_user_agent" TEXT, "last_seen_at" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
CREATE UNIQUE INDEX "trusted_fingerprints_fingerprint_unique" ON "trusted_fingerprints" ("fingerprint");
CREATE INDEX "trusted_fingerprints_created_at_idx" ON "trusted_fingerprints" ("created_at");
